(function(){"use strict";importScripts("https://cdn.jsdelivr.net/npm/cubejs@1.3.2/lib/cube.min.js"),importScripts("https://cdn.jsdelivr.net/npm/cubejs@1.3.2/lib/solve.js"),self.onmessage=function(t){const{type:s,facelets:r}=t.data;if(s==="init")try{Cube.initSolver(),self.postMessage({type:"init-done"})}catch(e){self.postMessage({type:"init-error",error:e.message})}if(s==="solve")try{const o=Cube.fromString(r).solve();self.postMessage({type:"solve-done",data:o})}catch(e){self.postMessage({type:"solve-error",error:e.message})}}})();
